window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-809774f2f1f478bd"]={"versions": [{"id": "FIG-809774f2f1f478bd", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert das Byte-Layout des Control Bit Vector (CBV), der innerhalb der User Data einer CAN-NM-PDU übertragen wird, um Steuerungs- und Statusinformationen über das Kommunikationsnetzwerk auszutauschen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 8-Bit-Feld gliedert sich in acht Zellen (Bit 7 bis Bit 0 von links nach rechts):</p>\n<ul class=\"fig-list\">\n<li>Bit 7 bis Bit 4: Reservierte bzw. unspezifizierte Bits (markiert mit <code>ed</code>).</li>\n<li>Bit 3: <code>Coordinator Sleep Ready</code> (Signalisiert die Bereitschaft eines NM-Koordinators zum Schlafen).</li>\n<li>Bit 2: <code>R3.2 NM Coordinator ID (High Bit)</code> (ausgegraut, Legacy-Koordinator-Identifikation).</li>\n<li>Bit 1: <code>R3.2 NM Coordinator ID (Low Bit)</code> (ausgegraut, Legacy-Koordinator-Identifikation).</li>\n<li>Bit 0: <code>Message Request</code> (Signalisiert die Anforderung zur wiederholten Übertragung von NM-Botschaften).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenkontext ist der Austausch zwischen CanNm-Instanzen auf dem CAN-Bus sowie die Übergabe an Schnittstellen wie CanIf und Nm.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitmasken-Darstellung ohne Kontrollfluss. Zur Laufzeit wird der Vektor bei der PDU-Zusammenstellung mit aktuellem Status belegt: Bit 0 fordert Botschaftswiederholungen an, Bit 3 synchronisiert koordinierte Netzwerkknoten hinsichtlich des Übergangs in den Schlafzustand, während Bit 2 und Bit 1 ehemals zur Koordinator-ID-Kodierung dienten. Empfangende Knoten werten die gesetzten Bits im Rahmen des Netzwerkmanagement-Zustandsautomaten aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der PDU-Payload-Struktur des CBV für Entwickler von BSW-Modulen (<code>CanNm</code>, <code>Nm</code>). Für Konformität müssen Sender und Empfänger exakt auf die Bitpositionen 3 (Coordinator Sleep Ready) und 0 (Message Request) zugreifen. Die Bits 2 und 1 tragen den Vermerk auf AUTOSAR R3.2 und dürfen in R4-Implementierungen nicht mehr aktiv als Koordinator-ID interpretiert werden. Bits 7 bis 4 sind reserviert und bei Übertragung auf Standardwerte zu setzen.</p>"}, {"id": "FIG-4fb08dbc917ae1e8", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert die Bitbelegung des Control Bit Vector (CBV), der als Steuerbyte in CAN-NM-PDUs übertragen wird, ergänzt um eine formale Bitpositionierung von <code>Bit 7</code> bis <code>Bit 0</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Byte-Feld ist explizit als <code>CBV</code> deklariert und umfasst 8 Bits in Big-Endian-/MSB-to-LSB-Darstellung:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code> (Kennzeichnung von Teilnetzwerk-Informationen)</li>\n<li><code>Bit 5</code>: <code>Reserved</code></li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code> (Kennzeichnung eines aktiven Weckereignisses durch den Knoten)</li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (High Bit)</code>)</li>\n<li><code>Bit 1</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (Low Bit)</code>)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Die Signale koppeln den CanNm-Zustandsautomaten mit Partial-Networking-Funktionalitäten und dem Nm-Koordinationsprotokoll.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitbelegung. Bei der Generierung einer CanNm-Botschaft setzt der Sender:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 0</code> (<code>Repeat Message Request</code>) zur Anforderung des Repeat Message State,</li>\n<li><code>Bit 3</code> (<code>NM Coordinator Sleep Ready Bit</code>) zur Freigabe des synchronisierten Schlafens,</li>\n<li><code>Bit 4</code> (<code>Active Wakeup Bit</code>), wenn das Aufwachen aktiv durch die lokale ECU initiiert wurde,</li>\n<li><code>Bit 6</code> (<code>Partial Network Information Bit</code>), wenn die PDU Teilnetzwerk-Filterdaten enthält.</li>\n</ul>\n<p class=\"fig-p\">Empfangende Knoten decodieren diese Flags zur Filterung und Zustandssteuerung. Bits 7, 5, 2 und 1 bleiben inaktiv bzw. reserviert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Stack-Implementierer (Module <code>CanNm</code>, <code>PduR</code>, <code>Nm</code>). Die Bitpositionen 6 (<code>Partial Network Information Bit</code>) und 4 (<code>Active Wakeup Bit</code>) sind für PN- und Wakeup-Tracking-Mechanismen verbindlich einzuhalten. Bit 2 und Bit 1 sind formal <code>Reserved</code>; die Altbezeichnungen weisen lediglich auf die Kompatibilitätshistorie zu AUTOSAR Release 3.2 hin. Reservierte Bits müssen senderseitig typischerweise auf 0 gesetzt und empfängerseitig ignoriert werden.</p>"}, {"id": "FIG-9f80cf204b259939", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert die Bitbelegung des Control Bit Vector (CBV), der als Steuerbyte in CAN-NM-PDUs übertragen wird, ergänzt um eine formale Bitpositionierung von <code>Bit 7</code> bis <code>Bit 0</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Byte-Feld ist explizit als <code>CBV</code> deklariert und umfasst 8 Bits in Big-Endian-/MSB-to-LSB-Darstellung:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code> (Kennzeichnung von Teilnetzwerk-Informationen)</li>\n<li><code>Bit 5</code>: <code>Reserved</code></li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code> (Kennzeichnung eines aktiven Weckereignisses durch den Knoten)</li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (High Bit)</code>)</li>\n<li><code>Bit 1</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (Low Bit)</code>)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Die Signale koppeln den CanNm-Zustandsautomaten mit Partial-Networking-Funktionalitäten und dem Nm-Koordinationsprotokoll.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitbelegung. Bei der Generierung einer CanNm-Botschaft setzt der Sender:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 0</code> (<code>Repeat Message Request</code>) zur Anforderung des Repeat Message State,</li>\n<li><code>Bit 3</code> (<code>NM Coordinator Sleep Ready Bit</code>) zur Freigabe des synchronisierten Schlafens,</li>\n<li><code>Bit 4</code> (<code>Active Wakeup Bit</code>), wenn das Aufwachen aktiv durch die lokale ECU initiiert wurde,</li>\n<li><code>Bit 6</code> (<code>Partial Network Information Bit</code>), wenn die PDU Teilnetzwerk-Filterdaten enthält.</li>\n</ul>\n<p class=\"fig-p\">Empfangende Knoten decodieren diese Flags zur Filterung und Zustandssteuerung. Bits 7, 5, 2 und 1 bleiben inaktiv bzw. reserviert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Stack-Implementierer (Module <code>CanNm</code>, <code>PduR</code>, <code>Nm</code>). Die Bitpositionen 6 (<code>Partial Network Information Bit</code>) und 4 (<code>Active Wakeup Bit</code>) sind für PN- und Wakeup-Tracking-Mechanismen verbindlich einzuhalten. Bit 2 und Bit 1 sind formal <code>Reserved</code>; die Altbezeichnungen weisen lediglich auf die Kompatibilitätshistorie zu AUTOSAR Release 3.2 hin. Reservierte Bits müssen senderseitig typischerweise auf 0 gesetzt und empfängerseitig ignoriert werden.</p>"}, {"id": "FIG-ba70c4284f8b3f8b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert die Bitbelegung des Control Bit Vector (CBV), der als Steuerbyte in CAN-NM-PDUs übertragen wird, ergänzt um eine formale Bitpositionierung von <code>Bit 7</code> bis <code>Bit 0</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Byte-Feld ist explizit als <code>CBV</code> deklariert und umfasst 8 Bits in Big-Endian-/MSB-to-LSB-Darstellung:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code> (Kennzeichnung von Teilnetzwerk-Informationen)</li>\n<li><code>Bit 5</code>: <code>Reserved</code></li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code> (Kennzeichnung eines aktiven Weckereignisses durch den Knoten)</li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (High Bit)</code>)</li>\n<li><code>Bit 1</code>: <code>Reserved</code> (unterlegt mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (Low Bit)</code>)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Die Signale koppeln den CanNm-Zustandsautomaten mit Partial-Networking-Funktionalitäten und dem Nm-Koordinationsprotokoll.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Bitbelegung. Bei der Generierung einer CanNm-Botschaft setzt der Sender:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 0</code> (<code>Repeat Message Request</code>) zur Anforderung des Repeat Message State,</li>\n<li><code>Bit 3</code> (<code>NM Coordinator Sleep Ready Bit</code>) zur Freigabe des synchronisierten Schlafens,</li>\n<li><code>Bit 4</code> (<code>Active Wakeup Bit</code>), wenn das Aufwachen aktiv durch die lokale ECU initiiert wurde,</li>\n<li><code>Bit 6</code> (<code>Partial Network Information Bit</code>), wenn die PDU Teilnetzwerk-Filterdaten enthält.</li>\n</ul>\n<p class=\"fig-p\">Empfangende Knoten decodieren diese Flags zur Filterung und Zustandssteuerung. Bits 7, 5, 2 und 1 bleiben inaktiv bzw. reserviert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für BSW-Stack-Implementierer (Module <code>CanNm</code>, <code>PduR</code>, <code>Nm</code>). Die Bitpositionen 6 (<code>Partial Network Information Bit</code>) und 4 (<code>Active Wakeup Bit</code>) sind für PN- und Wakeup-Tracking-Mechanismen verbindlich einzuhalten. Bit 2 und Bit 1 sind formal <code>Reserved</code>; die Altbezeichnungen weisen lediglich auf die Kompatibilitätshistorie zu AUTOSAR Release 3.2 hin. Reservierte Bits müssen senderseitig typischerweise auf 0 gesetzt und empfängerseitig ignoriert werden.</p>"}, {"id": "FIG-46b68695100470bd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert das standardisierte Byte-Format des Control Bit Vector (<code>CBV</code>) inklusive der Bitbelegungen für erweiterte Teilnetzwerk- und Abschaltfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 8-Bit-Register <code>CBV</code> besteht aus:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code></li>\n<li><code>Bit 5</code>: <code>Partial Network Learning Bit</code> (Kennzeichnung zur dynamischen Erlernung/Synchronisation von Teilnetzwerken)</li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code></li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code></li>\n<li><code>Bit 1</code>: <code>PN Shutdown Request Bit</code> (Anforderung zum synchronisierten Herunterfahren eines Teilnetzwerks)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Schnittstellen betreffen den CanNm-Zustandsautomaten, die PN-Management-Routinen sowie den Austausch zwischen verteilten ECUs über CAN.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsformat. Während des Betriebs interagiert der Knoten über spezifische Steuerbits:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 1</code> signalisiert eine strukturierte Abschaltanforderung für ein Teilnetzwerk (<code>PN Shutdown Request</code>),</li>\n<li><code>Bit 5</code> aktiviert oder markiert den Lernmodus für Teilnetzwerke (<code>Partial Network Learning</code>),</li>\n<li><code>Bit 4</code> markiert aktives Wecken,</li>\n<li><code>Bit 6</code> indiziert PN-Vektoren in den User Data,</li>\n<li><code>Bit 3</code> steuert die Schlafbereitschaft im Verbund,</li>\n<li><code>Bit 0</code> triggert den Wiederholungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Bits 7 und 2 verbleiben reserviert. Empfänger synchronisieren anhand dieser Flags ihre lokalen Zustandsmaschinen für Teilnetze und Koordination.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Bitmasken im CBV für CanNm. Entwickler müssen die funktionale Unterstützung für <code>PN Shutdown Request Bit</code> (Bit 1) und <code>Partial Network Learning Bit</code> (Bit 5) implementieren, sofern Teilnetzwerk-Erweiterungen aktiviert sind. Bit 2 ist ohne Verweis auf Legacy-Standards rein als <code>Reserved</code> deklariert; Bit 7 ist ebenfalls reserviert. Sender müssen reservierte Bits gemäss Spezifikation maskieren (üblicherweise auf logisch 0), Empfänger dürfen hierauf keine Statusänderungen stützen.</p>"}, {"id": "FIG-5592b18948fc76df", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert das standardisierte Byte-Format des Control Bit Vector (<code>CBV</code>) inklusive der Bitbelegungen für erweiterte Teilnetzwerk- und Abschaltfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 8-Bit-Register <code>CBV</code> besteht aus:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code></li>\n<li><code>Bit 5</code>: <code>Partial Network Learning Bit</code> (Kennzeichnung zur dynamischen Erlernung/Synchronisation von Teilnetzwerken)</li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code></li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code></li>\n<li><code>Bit 1</code>: <code>PN Shutdown Request Bit</code> (Anforderung zum synchronisierten Herunterfahren eines Teilnetzwerks)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Schnittstellen betreffen den CanNm-Zustandsautomaten, die PN-Management-Routinen sowie den Austausch zwischen verteilten ECUs über CAN.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsformat. Während des Betriebs interagiert der Knoten über spezifische Steuerbits:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 1</code> signalisiert eine strukturierte Abschaltanforderung für ein Teilnetzwerk (<code>PN Shutdown Request</code>),</li>\n<li><code>Bit 5</code> aktiviert oder markiert den Lernmodus für Teilnetzwerke (<code>Partial Network Learning</code>),</li>\n<li><code>Bit 4</code> markiert aktives Wecken,</li>\n<li><code>Bit 6</code> indiziert PN-Vektoren in den User Data,</li>\n<li><code>Bit 3</code> steuert die Schlafbereitschaft im Verbund,</li>\n<li><code>Bit 0</code> triggert den Wiederholungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Bits 7 und 2 verbleiben reserviert. Empfänger synchronisieren anhand dieser Flags ihre lokalen Zustandsmaschinen für Teilnetze und Koordination.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Bitmasken im CBV für CanNm. Entwickler müssen die funktionale Unterstützung für <code>PN Shutdown Request Bit</code> (Bit 1) und <code>Partial Network Learning Bit</code> (Bit 5) implementieren, sofern Teilnetzwerk-Erweiterungen aktiviert sind. Bit 2 ist ohne Verweis auf Legacy-Standards rein als <code>Reserved</code> deklariert; Bit 7 ist ebenfalls reserviert. Sender müssen reservierte Bits gemäss Spezifikation maskieren (üblicherweise auf logisch 0), Empfänger dürfen hierauf keine Statusänderungen stützen.</p>"}, {"id": "FIG-49a5bb507baaf132", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld-Spezifikation (Tabellen-/Layoutdiagramm) aus der AUTOSAR Classic Platform Spezifikation des CAN Network Management (<code>CanNm</code>). Das Diagramm visualisiert das standardisierte Byte-Format des Control Bit Vector (<code>CBV</code>) inklusive der Bitbelegungen für erweiterte Teilnetzwerk- und Abschaltfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das 8-Bit-Register <code>CBV</code> besteht aus:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 7</code>: <code>Reserved</code></li>\n<li><code>Bit 6</code>: <code>Partial Network Information Bit</code></li>\n<li><code>Bit 5</code>: <code>Partial Network Learning Bit</code> (Kennzeichnung zur dynamischen Erlernung/Synchronisation von Teilnetzwerken)</li>\n<li><code>Bit 4</code>: <code>Active Wakeup Bit</code></li>\n<li><code>Bit 3</code>: <code>NM Coordinator Sleep Ready Bit</code></li>\n<li><code>Bit 2</code>: <code>Reserved</code></li>\n<li><code>Bit 1</code>: <code>PN Shutdown Request Bit</code> (Anforderung zum synchronisierten Herunterfahren eines Teilnetzwerks)</li>\n<li><code>Bit 0</code>: <code>Repeat Message Request</code></li>\n</ul>\n<p class=\"fig-p\">Schnittstellen betreffen den CanNm-Zustandsautomaten, die PN-Management-Routinen sowie den Austausch zwischen verteilten ECUs über CAN.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bitbelegungsformat. Während des Betriebs interagiert der Knoten über spezifische Steuerbits:</p>\n<ul class=\"fig-list\">\n<li><code>Bit 1</code> signalisiert eine strukturierte Abschaltanforderung für ein Teilnetzwerk (<code>PN Shutdown Request</code>),</li>\n<li><code>Bit 5</code> aktiviert oder markiert den Lernmodus für Teilnetzwerke (<code>Partial Network Learning</code>),</li>\n<li><code>Bit 4</code> markiert aktives Wecken,</li>\n<li><code>Bit 6</code> indiziert PN-Vektoren in den User Data,</li>\n<li><code>Bit 3</code> steuert die Schlafbereitschaft im Verbund,</li>\n<li><code>Bit 0</code> triggert den Wiederholungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Bits 7 und 2 verbleiben reserviert. Empfänger synchronisieren anhand dieser Flags ihre lokalen Zustandsmaschinen für Teilnetze und Koordination.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Bitmasken im CBV für CanNm. Entwickler müssen die funktionale Unterstützung für <code>PN Shutdown Request Bit</code> (Bit 1) und <code>Partial Network Learning Bit</code> (Bit 5) implementieren, sofern Teilnetzwerk-Erweiterungen aktiviert sind. Bit 2 ist ohne Verweis auf Legacy-Standards rein als <code>Reserved</code> deklariert; Bit 7 ist ebenfalls reserviert. Sender müssen reservierte Bits gemäss Spezifikation maskieren (üblicherweise auf logisch 0), Empfänger dürfen hierauf keine Statusänderungen stützen.</p>"}], "trans": [{"from": "FIG-809774f2f1f478bd", "to": "FIG-4fb08dbc917ae1e8", "fr": "R4.0.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kopfzeile mit Bitpositionen <code>Bit 7</code> bis <code>Bit 0</code> sowie Zeilenbeschriftung <code>CBV</code> ergänzt.</li>\n<li>Bit 6: Belegung von unbeschriftet (<code>ed</code>) zu <code>Partial Network Information Bit</code> geändert.</li>\n<li>Bit 4: Belegung von unbeschriftet (<code>ed</code>) zu <code>Active Wakeup Bit</code> geändert.</li>\n<li>Bit 3: Beschriftung von <code>Coordinator Sleep Ready</code> zu <code>NM Coordinator Sleep Ready Bit</code> präzisiert.</li>\n<li>Bit 2 und Bit 1: Status <code>Reserved</code> explizit ergänzt (über den ausgegrauten Altbezeichnungen <code>R3.2 NM Coordinator ID (High Bit)</code> und <code>R3.2 NM Coordinator ID (Low Bit)</code>).</li>\n<li>Bit 0: Beschriftung von <code>Message Request</code> zu <code>Repeat Message Request</code> präzisiert.</li>\n</ul>"}, {"from": "FIG-4fb08dbc917ae1e8", "to": "FIG-9f80cf204b259939", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9f80cf204b259939", "to": "FIG-ba70c4284f8b3f8b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ba70c4284f8b3f8b", "to": "FIG-46b68695100470bd", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Bit 5: Belegung von <code>Reserved</code> zu <code>Partial Network Learning Bit</code> geändert.</li>\n<li>Bit 2: Ausgegrauter Altbezeichner <code>R3.2 NM Coordinator ID (High Bit)</code> entfernt; Bit verbleibt als rein <code>Reserved</code>.</li>\n<li>Bit 1: Belegung von <code>Reserved</code> (vormals mit ausgegrautem Altbezeichner <code>R3.2 NM Coordinator ID (Low Bit)</code>) zu <code>PN Shutdown Request Bit</code> geändert.</li>\n</ul>"}, {"from": "FIG-46b68695100470bd", "to": "FIG-5592b18948fc76df", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5592b18948fc76df", "to": "FIG-49a5bb507baaf132", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
